import org.jsoup.Connection;
import org.jsoup.nodes.*;
import org.junit.Test;
import java.nio.charset.Charset;
import java.nio.charset.StandardCharsets;
import java.util.List;

import static org.junit.Assert.*;
import static org.mockito.Mockito.*;

public class DocumentTest {

    @Test
    public void DocumentInitializationTest() {
        Document doc = new Document("http://test.com");
        assertNotNull(doc);
        assertEquals("http://test.com", doc.location());
    }

    @Test
    public void createShellTest() {
        Document doc = Document.createShell("http://test.com");
        assertNotNull(doc);
        assertEquals("http://test.com", doc.location());
    }

    @Test
    public void connectionTest() {
        Document doc = new Document("http://test.com");
        Connection connection = mock(Connection.class);

        Document updatedDoc = doc.connection(connection);
        assertNotNull(updatedDoc.connection());
    }

    @Test
    public void titleTest() {
        Document doc = new Document("http://test.com");
        doc.title("Test Title");
        assertEquals("Test Title", doc.title());
    }

    @Test
    public void charsetTest() {
        Document doc = new Document("http://test.com");
        doc.charset(StandardCharsets.UTF_8);

        Charset charset = doc.charset();
        assertEquals(StandardCharsets.UTF_8, charset);
    }

    @Test
    public void updateMetaCharsetElementTest() {
        Document doc = new Document("http://test.com");
        doc.updateMetaCharsetElement(true);
        assertTrue(doc.updateMetaCharsetElement());
    }

    @Test
    public void cloneTest() {
        Document doc = new Document("http://test.com");
        Document clonedDoc = doc.clone();

        assertNotEquals(doc, clonedDoc);
        assertEquals(doc.location(), clonedDoc.location());
    }

    @Test
    public void outputSettingsTest() {
        Document doc = new Document("http://test.com");

        Document.OutputSettings outputSettings = new Document.OutputSettings();
        doc.outputSettings(outputSettings);

        assertEquals(outputSettings, doc.outputSettings());
    }

    @Test
    public void parserTest() {
        Document doc = new Document("http://test.com");
        Parser parser = Parser.htmlParser();

        Document updatedDoc = doc.parser(parser);
        assertEquals(parser, updatedDoc.parser());
    }
}
